def transform(grid):
    # Preserve only the two patterned rectangular objects; remove all unrelated
    # speckles. Within the objects, fill the one-cell 4 intrusions.
    h,w=len(grid),len(grid[0]); out=[[6]*w for _ in range(h)]
    for y0,y1,x0,x1,color in [(3,4,15,21,8),(5,10,6,11,5)]:
        for y in range(y0,y1+1):
            for x in range(x0,x1+1): out[y][x]=color
    return out
